with filtered as (select id, account_id, txn_time, merchant, is_flagged, coalesce(merchant, 'Unknown') merchant_filled, hour(txn_time) txn_time_hour from transactions where merchant is not distinct from 'Grab' and txn_type = 'REFUND'), matched_keys as (select merchant from filtered intersect all select merchant from transactions where txn_type in ('REFUND', 'CREDIT', 'DEBIT')), reconciled as (select s.* from filtered s join matched_keys k on s.merchant = k.merchant), enriched as (select *, avg(txn_time_hour) over w_grp txn_time_hour_avg_7d from reconciled window w_grp as (partition by account_id order by cast(txn_time as bigint) range between 604800 preceding and current row)), with_windows as (select *, count(txn_time_hour) over w_running txn_time_hour_count_30d, min(txn_time_hour) over (partition by account_id, merchant) account_id_min_txn_time_hour, dense_rank() over (partition by account_id order by txn_time_hour desc nulls last) txn_time_hour_dense_rank from enriched window w_running as (partition by merchant order by cast(txn_time as bigint) range between 2592000 preceding and current row)), grouped as (select date_trunc('week', txn_time) as week_start, merchant, approx_percentile(txn_time_hour_count_30d, array(0.25, 0.5, 0.75)) as txn_time_hour_count_30d_quartiles, (unix_timestamp(max(txn_time)) - unix_timestamp(min(txn_time))) / 60 as duration_min from with_windows group by date_trunc('week', txn_time), merchant) select week_start, merchant, duration_min from grouped;
